# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the sets two players played against each other on start.gg, from player 1's side:
# per set the event, round and games (both characters, stage), plus who won and the scores.
# This is the data layer, so results are included; ds.ai.startgg leaves them out.
# Usage: `h2h = asyncio.run(head_to_head("Sparg0", "acola"))`
# ---------------------------------------------------------------------------
from __future__ import annotations

import asyncio
import datetime as dt
from typing import TYPE_CHECKING, Literal

from pydantic import BaseModel, Field

from ds.data.raw import startgg
from ds.data.startgg.lookup import PlayerLookup, resolve_player

if TYPE_CHECKING:
    from ds.data.raw.startgg import Set

__all__ = ["HeadToHead", "MatchupGame", "MatchupSet", "head_to_head", "matchup_sets"]

Side = Literal[1, 2]


class MatchupGame(BaseModel):
    """One game between the two players"""

    number: int
    char_group_1: str | None = Field(None, description="Player 1's pick (char.parquet `char_group`)")
    character_1: str | None = Field(None, description="Player 1's character as start.gg names it")
    char_group_2: str | None = None
    character_2: str | None = None
    stage: str | None = None
    winner: Side | None = Field(None, description="1 or 2: who won this game")


class MatchupSet(BaseModel):
    """One set between the two players"""

    date: dt.date
    tournament: str
    event: str
    event_slug: str = Field(description="start.gg/<event_slug> is the event's page")
    round: str | None = Field(None, description="eg 'Winners Final'")
    online: bool | None = None
    vod_url: str | None = None
    games: list[MatchupGame] = Field(description="[] when only the set score was reported")
    winner: Side | None = Field(None, description="1 or 2: who won the set")
    score_1: float | None = Field(None, description="Games player 1 won; -1 marks a DQ")
    score_2: float | None = None
    seed_1: int | None = None
    seed_2: int | None = None


class HeadToHead(BaseModel):
    """Every fetched set between two players, newest first, with the tally"""

    player_1: PlayerLookup
    player_2: PlayerLookup
    sets: list[MatchupSet]
    sets_won_1: int
    sets_won_2: int
    capped: bool = Field(description="True: `max_sets` was reached, older sets exist")


def matchup_sets(sets: list[Set], player_id: int) -> list[MatchupSet]:
    """Sets as rows seen from `player_id`'s side (player 1); sets they aren't in are skipped"""
    rows = []
    for s in sets:
        mine, theirs = s.side_of(player_id), s.opponent_of(player_id)
        if mine is None or theirs is None or s.completed_at is None:
            continue

        def side(entrant_id: int | None, mine_id: int | None = mine.entrant_id) -> Side | None:
            return None if entrant_id is None else 1 if entrant_id == mine_id else 2

        games = []
        for game in s.games:
            first, second = game.character_of(mine.entrant_id), game.character_of(theirs.entrant_id)
            games.append(
                MatchupGame(
                    number=game.number,
                    char_group_1=first.char_group if first else None,
                    character_1=first.name if first else None,
                    char_group_2=second.char_group if second else None,
                    character_2=second.name if second else None,
                    stage=game.stage.name if game.stage else None,
                    winner=side(game.winner_entrant_id),
                )
            )
        rows.append(
            MatchupSet(
                date=s.completed_at.date(),
                tournament=s.event.tournament.name if s.event and s.event.tournament else "",
                event=s.event.name if s.event else "",
                event_slug=s.event.slug if s.event else "",
                round=s.round_text,
                online=s.event.online if s.event else None,
                vod_url=s.vod_url,
                games=games,
                winner=side(s.winner_entrant_id),
                score_1=mine.score,
                score_2=theirs.score,
                seed_1=mine.seed,
                seed_2=theirs.seed,
            )
        )
    return rows


async def head_to_head(player_1: str, player_2: str, max_sets: int = 50) -> HeadToHead:
    """The sets two players played against each other, newest first (any date)

    Args:
        player_1: a tag, start.gg player id or profile url; rows are from this player's side.
        player_2: the opponent, same forms.
        max_sets: stop after this many sets.
    """
    first, second = await asyncio.gather(resolve_player(player_1), resolve_player(player_2))
    sets = await startgg.player_sets(first.player_id, opponent_id=second.player_id, max_sets=max_sets)
    rows = matchup_sets(sets, first.player_id)
    return HeadToHead(
        player_1=first,
        player_2=second,
        sets=rows,
        sets_won_1=sum(1 for row in rows if row.winner == 1),
        sets_won_2=sum(1 for row in rows if row.winner == 2),  # noqa: PLR2004  # side 2
        capped=len(sets) >= max_sets,
    )
